{
  "headline": "FDA's records trace our supply to a plant classified OAI 23 days before the posting",
  "headline_cites": ["E10", "E29"],
  "sentences": [
    {
      "text": "FDA first posted the fentanyl citrate injection shortage on 2012-01-01 and it remains current as of 2026-10-21.",
      "cites": ["E29", "E14"]
    },
    {
      "text": "Hospira, Inc. (FEI 1021343) is the labeler for NDC 00409909422 used at Corvale East and Corvale General.",
      "cites": ["E1", "E5", "E17"]
    },
    {
      "text": "FDA inspection 732886 of that plant ended 2011-06-17 and was classified OAI, 198 days before the shortage posting.",
      "cites": ["E10", "D10"]
    },
    {
      "text": "FDA inspection 740633 of the same plant ended 2011-08-04 and was classified OAI, 150 days before the shortage posting.",
      "cites": ["E11", "D11"]
    },
    {
      "text": "A Warning Letter was issued to the plant on 2010-04-12, 629 days before the shortage posting.",
      "cites": ["E16", "D7"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. (FEI 2220525) is the labeler for NDC 00641624810 used at Corvale General and Corvale Lakeside.",
      "cites": ["E4", "E7", "E25"]
    },
    {
      "text": "All FDA inspections of the Hikma plant from 2009 through 2024 have been classified VAI.",
      "cites": ["E18", "E19", "E20", "E21", "E22", "E23", "E24"]
    }
  ]
}
